static const char setup_html_before[] = "<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"pocket-nonce\" content=\"";
static const char setup_html_after[] = "\"><title>Connect Hermes Pocket</title>\n<style>body{font:16px system-ui,sans-serif;max-width:480px;margin:auto;padding:24px 18px;background:#101c25;color:#f4f1e9}h1{font-size:28px;margin:6px 0}p,small{line-height:1.5;color:#b9cbd6}section,details{background:#1a2c39;border:1px solid #365061;border-radius:16px;padding:18px;margin:18px 0}label{display:block;margin:16px 0 6px}input,textarea,select,button{box-sizing:border-box;width:100%;font:inherit;border-radius:10px;padding:13px;min-height:48px}input,textarea,select{background:#0c1922;color:#fff;border:1px solid #678091}button{background:#9ce4ce;color:#102820;border:0;font-weight:700;margin-top:12px;cursor:pointer}button.secondary{background:#2a4354;color:#fff}button:disabled{opacity:.6;cursor:wait}#result{white-space:pre-wrap;color:#ffd1a3;min-height:48px}#netstatus{font-size:14px}summary{cursor:pointer;padding:6px}small{display:block;margin-top:10px}.tag{color:#9ce4ce;font-size:13px;letter-spacing:2px}input[type=checkbox]{width:20px;min-height:20px;vertical-align:middle}#saved{color:#9ce4ce}</style>\n<div class=\"tag\">HERMES POCKET \u00b7 SETUP</div><h1>Let's get connected</h1><p>Choose your home Wi-Fi. Your phone stays on the Pocket hotspot until settings are saved.</p>\n<form id=\"setup\" novalidate><section><h2>1. Home Wi-Fi</h2><label for=\"networks\">Nearby networks \u00b7 2.4 GHz</label><select id=\"networks\"><option value=\"\">Choose a network\u2026</option></select><button id=\"scan\" type=\"button\" class=\"secondary\">Scan Wi-Fi</button><p id=\"netstatus\" role=\"status\">Tap Scan Wi-Fi to find nearby networks.</p><label for=\"ssid\">Network name</label><input id=\"ssid\" autocomplete=\"off\" maxlength=\"31\" placeholder=\"Select above, or type a hidden network\"><small>This is your router's Wi-Fi name, not the Pocket hotspot.</small><label for=\"password\">Wi-Fi password</label><input id=\"password\" type=\"password\" autocomplete=\"off\" maxlength=\"63\" placeholder=\"Your home Wi-Fi password\"><label><input id=\"showpass\" type=\"checkbox\"> Show password</label></section>\n<details><summary>2. Hermes connection \u00b7 optional for now</summary><p>Leave these blank to set up Wi-Fi first. Only use your dedicated Pocket pairing token.</p><label for=\"windows\">Windows bridge HTTPS address</label><input id=\"windows\" placeholder=\"https://your-bridge.example\" maxlength=\"192\"><label for=\"linux\">Linux bridge HTTPS address</label><input id=\"linux\" placeholder=\"https://your-bridge.example\" maxlength=\"192\"><label for=\"token\">Pocket pairing token</label><input id=\"token\" type=\"password\" maxlength=\"128\" autocomplete=\"off\"><label for=\"ca\">Bridge CA certificate \u00b7 optional</label><textarea id=\"ca\" maxlength=\"2048\" rows=\"4\"></textarea><small>Blank fields remove existing bridge pairing. Settings are stored in unencrypted device flash. Never enter provider API keys here.</small></details>\n<p id=\"result\" role=\"alert\" aria-live=\"assertive\"></p><button id=\"save\" type=\"submit\">Save Wi-Fi and restart</button><p id=\"saved\" role=\"status\"></p><small>The hotspot expires after 5 minutes. If it expires, hold OK on Pocket to reopen setup. Saving restarts Pocket; then reconnect your phone to your normal Wi-Fi.</small></form>\n<script>\n'use strict';\nconst $=id=>document.getElementById(id);\nconst form=$('setup'),saveButton=$('save'),scanButton=$('scan'),status=$('result');\nconst byteLength=s=>new TextEncoder().encode(s).length;\nfunction validateSettings(b){\n if(!b.ssid||byteLength(b.ssid)>31)return 'Choose your home Wi-Fi, or enter a network name of at most 31 bytes.';\n if(byteLength(b.password)<8||byteLength(b.password)>63)return 'Wi-Fi password must be 8\u201363 bytes. Enter your home router password.';\n for(const key of ['windows','linux'])if(b[key]&&(byteLength(b[key])>192||!/^https:\\/\\/[^\\s@?#]+$/.test(b[key])))return 'Use an HTTPS bridge address, or leave the optional Hermes fields blank.';\n if(b.token&&(b.token.length<32||b.token.length>128||!/^[\\x21-\\x7e]+$/.test(b.token)))return 'Pocket pairing token must be 32\u2013128 visible characters, or leave it blank.';\n if(byteLength(b.ca)>2048||(b.ca&&(!b.ca.startsWith('-----BEGIN CERTIFICATE-----')||!b.ca.includes('-----END CERTIFICATE-----'))))return 'Enter a valid PEM certificate, or leave the optional certificate blank.';\n return '';\n}\nasync function request(path,options){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),15000);try{return await fetch(path,{...options,signal:controller.signal,cache:'no-store'})}finally{clearTimeout(timer)}}\nfunction nonce(){return document.querySelector('meta[name=\"pocket-nonce\"]').content}\n$('showpass').addEventListener('change',()=>{$('password').type=$('showpass').checked?'text':'password'});\n$('networks').addEventListener('change',()=>{if($('networks').value){$('ssid').value=$('networks').value;$('password').focus()}});\nscanButton.addEventListener('click',async()=>{scanButton.disabled=true;$('netstatus').textContent='Scanning nearby Wi-Fi\u2026';try{const r=await request('/networks',{headers:{'X-Pocket-Setup':nonce()}});if(!r.ok)throw new Error(await r.text());const data=await r.json();const list=$('networks');list.replaceChildren();const first=document.createElement('option');first.value='';first.textContent='Choose a network\u2026';list.appendChild(first);for(const n of data.networks){const o=document.createElement('option');o.value=n.ssid;o.textContent=n.ssid+' \u00b7 '+(n.rssi>-60?'Strong':n.rssi>-75?'Fair':'Weak')+(n.open?' \u00b7 Open network unsupported':'');o.disabled=n.open;list.appendChild(o)}$('netstatus').textContent=data.networks.length?'Select your network, then enter its password.':'No networks found. Scan again, or type the name below.'}catch(e){$('netstatus').textContent='Scan unavailable. You can type your network name below. '+e.message}finally{scanButton.disabled=false}});\nform.addEventListener('submit',async e=>{e.preventDefault();if(saveButton.disabled)return;const b={};for(const key of ['ssid','password','windows','linux','token','ca'])b[key]=$(key).value;if(validateSettings(b)){status.textContent=validateSettings(b);return}status.textContent='Saving settings\u2026';saveButton.disabled=true;scanButton.disabled=true;try{const r=await request('/save',{method:'POST',headers:{'Content-Type':'application/json','X-Pocket-Setup':nonce()},body:JSON.stringify(b)});const text=await r.text();if(!r.ok){status.textContent=text+'\\nCheck the fields and try again. If setup expired, hold OK on Pocket and reconnect.';saveButton.disabled=false;scanButton.disabled=false;return}status.textContent='';$('saved').textContent='Saved! Pocket is restarting. Reconnect your phone to your normal Wi-Fi and check Pocket\u2019s screen.';saveButton.textContent='Saved \u00b7 restarting';$('password').value='';$('token').value=''}catch(e){status.textContent='Could not confirm saving. Check Pocket\u2019s screen. If it did not restart, reconnect to its setup hotspot and try again.';saveButton.disabled=false;scanButton.disabled=false}});\n</script></html>\n";
